func:
var raw = msg.payload;

if (typeof raw === "string") {
    try {
        raw = JSON.parse(raw);
    } catch (error) {
        node.error(
            "Invalid telemetry JSON",
            msg
        );

        return null;
    }
}

raw = raw || {};

var trueState =
    raw.true_state || {};

var inputs =
    raw.inputs || {};

var control =
    raw.control || {};

var operatingMode =
    raw.operating_mode || {};

var health =
    raw.health || {};

var fault =
    raw.fault || {};

var effects =
    raw.fault_effects || {};

function numeric(
    primaryValue,
    fallbackValue,
    defaultValue
) {
    var selected =
        primaryValue !== undefined &&
        primaryValue !== null
            ? primaryValue
            : fallbackValue;

    var result =
        Number(selected);

    return Number.isFinite(result)
        ? result
        : defaultValue;
}

var now =
    Date.now();

var previousReceiveTime =
    context.get(
        "previousReceiveTime"
    );

var interArrivalMs =
    previousReceiveTime !== undefined
        ? now - previousReceiveTime
        : null;

context.set(
    "previousReceiveTime",
    now
);

var sequenceId =
    numeric(
        raw.sequence_id,
        null,
        0
    );

var previousSequence =
    context.get(
        "previousSequence"
    );

var sequenceGap =
    previousSequence !== undefined
        ? sequenceId -
          previousSequence
        : null;

context.set(
    "previousSequence",
    sequenceId
);

var streamStatus =
    interArrivalMs === null ||
    interArrivalMs <= 2500
        ? "LIVE"
        : "DELAYED";

var synchronisationStatus;

if (
    sequenceGap === null ||
    sequenceGap === 1
) {
    synchronisationStatus =
        streamStatus === "LIVE"
            ? "SYNCHRONISED"
            : "DELAYED";
} else {
    synchronisationStatus =
        "SEQUENCE GAP";
}

var temperature =
    numeric(
        trueState.temperature_c,
        raw.temp,
        0
    );

var rpm =
    numeric(
        trueState.speed_rpm,
        raw.rpm,
        0
    );

var current =
    numeric(
        trueState.current_a,
        raw.current,
        0
    );

var vibration =
    numeric(
        trueState.vibration_g,
        raw.vibration,
        0
    );

var supplyVoltage =
    numeric(
        inputs.supply_voltage_v,
        230,
        230
    );

var power =
    numeric(
        trueState.power_w,
        current *
        supplyVoltage,
        0
    );

var energy =
    numeric(
        trueState.energy_wh,
        null,
        0
    );

var coolingRate =
    numeric(
        trueState
            .cooling_rate_c_per_s,
        null,
        0
    );

var coolingEfficiency =
    numeric(
        trueState
            .cooling_efficiency,
        effects
            .cooling_efficiency,
        1
    );

var thermalResistance =
    numeric(
        trueState
            .thermal_resistance_c_per_w,
        effects
            .thermal_resistance_c_per_w,
        0.18
    );

var GRID_CO2_G_PER_WH =
    0.233;

var co2 =
    energy *
    GRID_CO2_G_PER_WH;

var thermalEff =
    Math.abs(coolingRate) /
    Math.max(1, power) *
    100000;

var speedCommandPct =
    numeric(
        inputs.speed_command_pct,
        null,
        0
    );

var targetRpm =
    speedCommandPct /
    100 *
    3000;

var speedErrorRpm =
    rpm -
    targetRpm;

var anomaly =
    fault.active === true ||
    raw.anomaly === true;

var normalised = {
    assetId:
        raw.asset_id ||
        "UNKNOWN",

    schemaVersion:
        raw.schema_version ||
        "",

    modelVersion:
        raw.model_version ||
        "",

    sequenceId:
        sequenceId,

    sequenceGap:
        sequenceGap,

    sourceTimeMs:
        numeric(
            raw.source_time_ms,
            raw.timestamp,
            0
        ),

    receiveTimeMs:
        now,

    interArrivalMs:
        interArrivalMs,

    streamStatus:
        streamStatus,

    synchronisationStatus:
        synchronisationStatus,

    controlMode:
        raw.control_mode ||
        control.mode ||
        "UNKNOWN",

    operatingMode:
        operatingMode.label ||
        "UNKNOWN",

    operatingModeCode:
        numeric(
            operatingMode.code,
            null,
            0
        ),

    speedCommandPct:
        speedCommandPct,

    targetRpm:
        Number(
            targetRpm.toFixed(1)
        ),

    speedErrorRpm:
        Number(
            speedErrorRpm.toFixed(1)
        ),

    processHeatLoadW:
        numeric(
            inputs
                .process_heat_load_w,
            null,
            0
        ),

    effectiveProcessHeatLoadW:
        numeric(
            effects
                .effective_process_heat_load_w,
            inputs
                .process_heat_load_w,
            0
        ),

    mechanicalLoad:
        numeric(
            inputs.mechanical_load,
            null,
            0
        ),

    effectiveMechanicalLoad:
        numeric(
            effects
                .effective_mechanical_load,
            inputs.mechanical_load,
            0
        ),

    ambientTemperatureC:
        numeric(
            inputs
                .ambient_temperature_c,
            null,
            0
        ),

    humidityPct:
        numeric(
            inputs.humidity_pct,
            null,
            0
        ),

    dustLevel:
        numeric(
            inputs.dust_level,
            null,
            0
        ),

    supplyVoltageV:
        supplyVoltage,

    temp:
        Number(
            temperature.toFixed(2)
        ),

    rpm:
        Math.round(rpm),

    current:
        Number(
            current.toFixed(3)
        ),

    vibration:
        Number(
            vibration.toFixed(4)
        ),

    power:
        Number(
            power.toFixed(2)
        ),

    energy:
        Number(
            energy.toFixed(4)
        ),

    coolingRate:
        Number(
            coolingRate.toFixed(5)
        ),

    coolingEfficiency:
        Number(
            coolingEfficiency
                .toFixed(4)
        ),

    thermalResistance:
        Number(
            thermalResistance
                .toFixed(4)
        ),

    thermalEff:
        Number(
            thermalEff.toFixed(3)
        ),

    co2:
        Number(
            co2.toFixed(4)
        ),

    healthOverall:
        numeric(
            health.overall,
            null,
            100
        ),

    healthStatus:
        health.status ||
        "UNKNOWN",

    faultCode:
        fault.code ||
        "F0",

    faultClassId:
        numeric(
            fault.class_id,
            null,
            0
        ),

    faultBinaryLabel:
        numeric(
            fault.binary_label,
            anomaly ? 1 : 0,
            0
        ),

    faultLabel:
        fault.label ||
        "healthy",

    faultSeverity:
        numeric(
            fault.severity,
            null,
            0
        ),

    faultActive:
        fault.active === true,

    faultActivatedAtMs:
        numeric(
            fault.activated_at_ms,
            null,
            0
        ),

    faultLastChangeMs:
        numeric(
            fault
                .last_change_time_ms,
            null,
            0
        ),

    currentMultiplier:
        numeric(
            effects
                .current_multiplier,
            null,
            1
        ),

    vibrationOffsetG:
        numeric(
            effects
                .vibration_offset_g,
            null,
            0
        ),

    addedHeatLoadW:
        numeric(
            effects
                .added_heat_load_w,
            null,
            0
        ),

    anomaly:
        anomaly,

    acceptedCommands:
        numeric(
            control
                .accepted_commands,
            null,
            0
        ),

    rejectedCommands:
        numeric(
            control
                .rejected_commands,
            null,
            0
        ),

    lastCommandTimeMs:
        numeric(
            control
                .last_command_time_ms,
            null,
            0
        ),

    experimentRunId:
        flow.get(
            "experimentRunId"
        ) || "",

    experimentPhase:
        flow.get(
            "experimentPhase"
        ) || "IDLE",

    selectedFaultCode:
        flow.get(
            "selectedFaultCode"
        ) || "F0",

    selectedFaultSeverity:
        Number(
            flow.get(
                "selectedFaultSeverity"
            ) || 0
        ),

    selectedReplicate:
        Number(
            flow.get(
                "selectedReplicate"
            ) || 1
        ),

    ts:
        now
};

msg.payload =
    normalised;

msg.data =
    normalised;

flow.set(
    "latestTwinState",
    normalised
);

return msg;

msg.topic = "Temperature (°C)";
msg.payload = msg.payload.temp;
return msg;

msg.topic = "Fan Speed (RPM)";
msg.payload = msg.payload.rpm;
return msg;

msg.topic = "Motor Current (A)";
msg.payload = msg.payload.current;
return msg;

msg.topic = "Vibration (g RMS)";
msg.payload = msg.payload.vibration;
return msg;

msg.topic = "Power (W)";
msg.payload = msg.payload.power;
return msg;

msg.topic = "Energy (Wh)";
msg.payload = msg.payload.energy;
return msg;

msg.topic = "Cooling Rate (°C/s)";
msg.payload = msg.payload.coolingRate;
return msg;

msg.topic = "Thermal Efficiency (idx)";
msg.payload = msg.payload.thermalEff;
return msg;

msg.topic = "CO2 (g)";
msg.payload = msg.payload.co2;
return msg;

var state =
    msg.payload || {};

var active =
    state.anomaly === true;

var previous =
    context.get(
        "previousFaultActive"
    );

context.set(
    "previousFaultActive",
    active
);

var toast =
    null;

if (
    active &&
    previous !== true
) {
    toast = {
        topic:
            "FAULT ACTIVE",

        payload:
            state.faultCode +
            " — " +
            state.faultLabel +
            " | severity " +
            Number(
                state.faultSeverity ||
                0
            ).toFixed(2)
    };
}

return [
    toast,
    msg
];

var d = msg.data || msg.payload || {};

msg.headers = { "Content-Type": "application/json" };

msg.payload = {
    temp: Number(d.temp),
    rpm: Number(d.rpm),
    current: Number(d.current),
    vibration: Number(d.vibration),
    power: Number(d.power),
    energy: Number(d.energy),
    coolingRate: Number(d.coolingRate),
    thermalEff: Number(d.thermalEff),
    co2: Number(d.co2)
};

return msg;

var ai = msg.payload || {};
var processState = msg.data || {};

var storedAI = {
    fault_code:
        ai.fault_code,

    fault_label:
        ai.fault_label,

    confidence:
        ai.confidence,

    severity:
        ai.severity,

    advice:
        ai.advice,

    received_at_ms:
        Date.now()
};

flow.set(
    "latestAI",
    storedAI
);

msg.ai = ai;
msg.payload = processState;

return msg;

var ai = msg.ai || {};
msg.payload = ai.fault_label || "Unknown";
return msg;

var ai = msg.ai || {};
var conf = 0;
if (ai.confidence !== undefined && ai.confidence !== null) {
    conf = Number(ai.confidence) * 100;
}
msg.payload = conf;
return msg;

var ai = msg.ai || {};
msg.topic = "Fault Code";
var fc = (ai.fault_code !== undefined && ai.fault_code !== null) ? ai.fault_code : 0;
msg.payload = Number(fc);
return msg;

var ai = msg.ai || {};
msg.payload = ai.advice || "AI maintenance recommendation will appear here once the trained model is deployed.";
return msg;

var state =
    msg.payload || {};

if (
    flow.get(
        "loggingActive"
    ) !== true
) {
    return null;
}

var now =
    Date.now();

var start =
    Number(
        flow.get(
            "logStartMs"
        ) || 0
    );

var runId =
    flow.get(
        "logRunId"
    );

if (
    !start ||
    !runId
) {
    return null;
}

var MAX_WINDOW_MS =
    10 *
    60 *
    1000;

var elapsedMs =
    now -
    start;

if (
    elapsedMs >=
    MAX_WINDOW_MS
) {
    flow.set(
        "loggingActive",
        false
    );

    return null;
}

var ai =
    flow.get(
        "latestAI"
    ) || {};

var aiAgeMs =
    ai.received_at_ms
        ? now -
          ai.received_at_ms
        : null;

if (
    aiAgeMs === null ||
    aiAgeMs > 5000
) {
    ai = {};
}

function valueOrBlank(
    value
) {
    if (
        value === undefined ||
        value === null ||
        Number.isNaN(value)
    ) {
        return "";
    }

    return value;
}

var phase =
    flow.get(
        "experimentPhase"
    ) || "UNKNOWN";

var selectedFaultCode =
    flow.get(
        "selectedFaultCode"
    ) || "F0";

var selectedFaultSeverity =
    Number(
        flow.get(
            "selectedFaultSeverity"
        ) || 0
    );

var replicate =
    Number(
        flow.get(
            "selectedReplicate"
        ) || 1
    );

var record = {
    ts_iso:
        new Date(
            state.ts ||
            now
        ).toISOString(),

    ts_ms:
        state.ts ||
        now,

    run_id:
        runId,

    replicate:
        replicate,

    experiment_elapsed_s:
        Number(
            (
                elapsedMs /
                1000
            ).toFixed(3)
        ),

    experiment_phase:
        phase,

    selected_fault_code:
        selectedFaultCode,

    selected_fault_severity:
        selectedFaultSeverity,

    asset_id:
        state.assetId ||
        "",

    schema_version:
        state.schemaVersion ||
        "",

    model_version:
        state.modelVersion ||
        "",

    sequence_id:
        valueOrBlank(
            state.sequenceId
        ),

    sequence_gap:
        valueOrBlank(
            state.sequenceGap
        ),

    stream_status:
        state.streamStatus ||
        "",

    synchronisation_status:
        state
            .synchronisationStatus ||
        "",

    control_mode:
        state.controlMode ||
        "",

    operating_mode:
        state.operatingMode ||
        "",

    speed_command_pct:
        valueOrBlank(
            state.speedCommandPct
        ),

    target_rpm:
        valueOrBlank(
            state.targetRpm
        ),

    actual_rpm:
        valueOrBlank(
            state.rpm
        ),

    speed_error_rpm:
        valueOrBlank(
            state.speedErrorRpm
        ),

    process_heat_load_w:
        valueOrBlank(
            state.processHeatLoadW
        ),

    effective_process_heat_load_w:
        valueOrBlank(
            state
                .effectiveProcessHeatLoadW
        ),

    mechanical_load:
        valueOrBlank(
            state.mechanicalLoad
        ),

    effective_mechanical_load:
        valueOrBlank(
            state
                .effectiveMechanicalLoad
        ),

    ambient_temperature_c:
        valueOrBlank(
            state
                .ambientTemperatureC
        ),

    temperature_c:
        valueOrBlank(
            state.temp
        ),

    current_a:
        valueOrBlank(
            state.current
        ),

    current_multiplier:
        valueOrBlank(
            state.currentMultiplier
        ),

    vibration_g:
        valueOrBlank(
            state.vibration
        ),

    vibration_offset_g:
        valueOrBlank(
            state.vibrationOffsetG
        ),

    power_w:
        valueOrBlank(
            state.power
        ),

    energy_wh:
        valueOrBlank(
            state.energy
        ),

    cooling_rate_c_per_s:
        valueOrBlank(
            state.coolingRate
        ),

    cooling_efficiency:
        valueOrBlank(
            state.coolingEfficiency
        ),

    thermal_resistance_c_per_w:
        valueOrBlank(
            state.thermalResistance
        ),

    legacy_thermal_eff_index:
        valueOrBlank(
            state.thermalEff
        ),

    co2_g:
        valueOrBlank(
            state.co2
        ),

    health_overall:
        valueOrBlank(
            state.healthOverall
        ),

    health_status:
        state.healthStatus ||
        "",

    embedded_fault_code:
        state.faultCode ||
        "",

    embedded_fault_class_id:
        valueOrBlank(
            state.faultClassId
        ),

    embedded_fault_binary_label:
        valueOrBlank(
            state.faultBinaryLabel
        ),

    embedded_fault_label:
        state.faultLabel ||
        "",

    embedded_fault_severity:
        valueOrBlank(
            state.faultSeverity
        ),

    embedded_fault_active:
        state.faultActive === true
            ? 1
            : 0,

    anomaly:
        state.anomaly === true
            ? 1
            : 0,

    ai_fault_code:
        valueOrBlank(
            ai.fault_code
        ),

    ai_fault_label:
        ai.fault_label ||
        "",

    ai_confidence:
        valueOrBlank(
            ai.confidence
        ),

    ai_severity:
        ai.severity ||
        "",

    accepted_commands:
        valueOrBlank(
            state.acceptedCommands
        ),

    rejected_commands:
        valueOrBlank(
            state.rejectedCommands
        )
};

var columns =
    Object.keys(record);

function escapeCsv(
    value
) {
    var text =
        value === undefined ||
        value === null
            ? ""
            : String(value);

    if (
        text.includes(",") ||
        text.includes("\"") ||
        text.includes("\n") ||
        text.includes("\r")
    ) {
        return "\"" +
            text.replace(
                /"/g,
                "\"\""
            ) +
            "\"";
    }

    return text;
}

var headerKey =
    "csvHeaderWritten:" +
    runId;

var headerWritten =
    flow.get(
        headerKey
    ) === true;

var row =
    columns
        .map(
            function(column) {
                return escapeCsv(
                    record[column]
                );
            }
        )
        .join(",");

var content = "";

if (!headerWritten) {
    content +=
        columns.join(",") +
        "\n";

    flow.set(
        headerKey,
        true
    );
}

content +=
    row +
    "\n";

msg.filename =
    "C:\\ProjectFiles\\Digital_Twin_MQTT\\data\\V3\\" +
    runId +
    ".csv";

msg.payload =
    content;

return msg;

var pending =
    flow.get("pendingControl") || {
        control_mode: "MANUAL",
        speed_command_pct: 65,
        process_heat_load_w: 145,
        mechanical_load: 0.30
    };

if (msg.topic === "control_mode") {
    pending.control_mode =
        String(msg.payload);
}

if (msg.topic === "speed_command_pct") {
    pending.speed_command_pct =
        Number(msg.payload);
}

if (msg.topic === "process_heat_load_w") {
    pending.process_heat_load_w =
        Number(msg.payload);
}

if (msg.topic === "mechanical_load") {
    pending.mechanical_load =
        Number(msg.payload);
}

flow.set(
    "pendingControl",
    pending
);

msg.payload = pending;

return msg;

var pending =
    flow.get("pendingControl") || {
        control_mode: "MANUAL",
        speed_command_pct: 65,
        process_heat_load_w: 145,
        mechanical_load: 0.30
    };

function validNumber(value, minimum, maximum) {
    var numericValue = Number(value);

    return (
        Number.isFinite(numericValue) &&
        numericValue >= minimum &&
        numericValue <= maximum
    );
}

if (pending.control_mode === "AUTOMATIC") {
    msg.payload = {
        automatic: true
    };

    return msg;
}

if (
    pending.control_mode !== "MANUAL" ||
    !validNumber(
        pending.speed_command_pct,
        0,
        100
    ) ||
    !validNumber(
        pending.process_heat_load_w,
        0,
        500
    ) ||
    !validNumber(
        pending.mechanical_load,
        0,
        1
    )
) {
    node.error(
        "Supervisory command failed validation",
        msg
    );

    return null;
}

msg.payload = {
    control_mode: "MANUAL",
    speed_command_pct:
        Number(
            pending.speed_command_pct
        ),
    process_heat_load_w:
        Number(
            pending.process_heat_load_w
        ),
    mechanical_load:
        Number(
            pending.mechanical_load
        )
};

return msg;

var command = msg.payload;

if (typeof command === "string") {
    try {
        command = JSON.parse(command);
    } catch (error) {
        node.error(
            "Invalid command JSON",
            msg
        );

        return null;
    }
}

var state =
    flow.get("latestTwinState") || {};

var dispatch = {
    dispatchTimeMs:
        Date.now(),

    acceptedBefore:
        Number(
            state.acceptedCommands || 0
        ),

    rejectedBefore:
        Number(
            state.rejectedCommands || 0
        ),

    command:
        command
};

flow.set(
    "lastCommandDispatch",
    dispatch
);

msg.topic =
    "factory/fan/command";

msg.payload =
    JSON.stringify(command);

return msg;

var state = msg.payload || {};

var dispatch =
    flow.get("lastCommandDispatch");

var acknowledgement =
    flow.get("lastAcknowledgement") || {
        status: "NO COMMAND",
        responseTimeMs: null
    };

if (dispatch) {
    if (
        Number(state.acceptedCommands) >
        Number(dispatch.acceptedBefore)
    ) {
        acknowledgement = {
            status: "ACCEPTED",
            responseTimeMs:
                Date.now() -
                dispatch.dispatchTimeMs
        };

        flow.set(
            "lastAcknowledgement",
            acknowledgement
        );

        flow.set(
            "lastCommandDispatch",
            null
        );

    } else if (
        Number(state.rejectedCommands) >
        Number(dispatch.rejectedBefore)
    ) {
        acknowledgement = {
            status: "REJECTED",
            responseTimeMs:
                Date.now() -
                dispatch.dispatchTimeMs
        };

        flow.set(
            "lastAcknowledgement",
            acknowledgement
        );

        flow.set(
            "lastCommandDispatch",
            null
        );

    } else {
        acknowledgement = {
            status: "AWAITING RESPONSE",
            responseTimeMs:
                Date.now() -
                dispatch.dispatchTimeMs
        };
    }
}

return [
    {
        payload:
            state.controlMode
    },
    {
        payload:
            state.operatingMode
    },
    {
        payload:
            state.speedCommandPct
    },
    {
        payload:
            state.targetRpm
    },
    {
        payload:
            state.rpm
    },
    {
        payload:
            acknowledgement.status
    },
    {
        payload:
            acknowledgement.responseTimeMs === null
                ? "—"
                : acknowledgement.responseTimeMs
    },
    {
        payload:
            state.acceptedCommands +
            " accepted / " +
            state.rejectedCommands +
            " rejected"
    },
    {
        payload:
            state.healthStatus +
            " | " +
            state.faultCode
    }
];

var state = msg.payload || {};

return [
    {
        topic: "Target RPM",
        payload: Number(
            state.targetRpm || 0
        )
    },
    {
        topic: "Actual RPM",
        payload: Number(
            state.rpm || 0
        )
    }
];

var config =
    flow.get(
        "experimentConfig"
    ) || {
        fault_code: "F1",
        fault_severity: 0.6,
        replicate: 1
    };

var faultCode =
    String(
        config.fault_code ||
        "F1"
    );

var severity =
    Number(
        config.fault_severity
    );

var replicate =
    Math.max(
        1,
        Math.floor(
            Number(
                config.replicate
            ) || 1
        )
    );

if (
    faultCode !== "F0" &&
    (
        !Number.isFinite(
            severity
        ) ||
        severity <= 0 ||
        severity > 1
    )
) {
    return [
        null,
        {
            payload:
                "ERROR — select severity 0.1–1.0 for " +
                faultCode
        }
    ];
}

if (
    flow.get(
        "loggingActive"
    ) === true
) {
    return [
        null,
        {
            payload:
                "RUN ALREADY ACTIVE — stop it before starting another"
        }
    ];
}

var now =
    Date.now();

var stamp =
    new Date(now)
        .toISOString()
        .replace(
            /[-:]/g,
            ""
        )
        .replace(
            /\..+/,
            ""
        );

var severityCode =
    faultCode === "F0"
        ? "S00"
        : "S" +
          String(
              Math.round(
                  severity *
                  10
              )
          ).padStart(
              2,
              "0"
          );

var runId =
    "FAN_DT_001_" +
    faultCode +
    "_" +
    severityCode +
    "_R" +
    String(
        replicate
    ).padStart(
        2,
        "0"
    ) +
    "_" +
    stamp;

flow.set(
    "logStartMs",
    now
);

flow.set(
    "logRunId",
    runId
);

flow.set(
    "experimentRunId",
    runId
);

flow.set(
    "loggingActive",
    true
);

flow.set(
    "experimentPhase",
    "BASELINE"
);

flow.set(
    "selectedFaultCode",
    faultCode
);

flow.set(
    "selectedFaultSeverity",
    severity
);

flow.set(
    "selectedReplicate",
    replicate
);

flow.set(
    "csvHeaderWritten:" +
    runId,
    false
);

var oldTimers =
    context.get(
        "experimentTimers"
    ) || [];

oldTimers.forEach(
    function(timer) {
        clearTimeout(timer);
    }
);

/*
  0–60 s:
  Healthy baseline
*/

var baselineTimer =
    setTimeout(
        function() {
            flow.set(
                "experimentPhase",
                "FAULT_ACTIVE"
            );

            if (
                faultCode !== "F0"
            ) {
                node.send([
                    {
                        payload: {
                            fault_code:
                                faultCode,

                            fault_severity:
                                severity
                        }
                    },
                    {
                        payload:
                            "FAULT ACTIVE — " +
                            faultCode +
                            " | severity " +
                            severity.toFixed(1)
                    }
                ]);

            } else {
                node.send([
                    {
                        payload: {
                            clear_fault:
                                true
                        }
                    },
                    {
                        payload:
                            "HEALTHY SCENARIO ACTIVE — F0"
                    }
                ]);
            }
        },
        60 * 1000
    );

/*
  540–600 s:
  Recovery
*/

var recoveryTimer =
    setTimeout(
        function() {
            flow.set(
                "experimentPhase",
                "RECOVERY"
            );

            node.send([
                {
                    payload: {
                        clear_fault:
                            true
                    }
                },
                {
                    payload:
                        "RECOVERY — fault cleared | 60 s remaining"
                }
            ]);
        },
        540 * 1000
    );

/*
  Stop at 600 s.
*/

var stopTimer =
    setTimeout(
        function() {
            flow.set(
                "loggingActive",
                false
            );

            flow.set(
                "experimentPhase",
                "COMPLETE"
            );

            node.send([
                {
                    payload: {
                        clear_fault:
                            true
                    }
                },
                {
                    payload:
                        "COMPLETE — 10-minute CSV saved | " +
                        runId
                }
            ]);
        },
        600 * 1000
    );

context.set(
    "experimentTimers",
    [
        baselineTimer,
        recoveryTimer,
        stopTimer
    ]
);

/*
  Initial command:
  - clear any previous fault;
  - reset energy for this run.
*/

return [
    {
        payload: {
            clear_fault:
                true,

            reset_energy:
                true
        }
    },
    {
        payload:
            "BASELINE — 60 s | " +
            runId
    }
];

var pending = {
    control_mode: "AUTOMATIC",
    speed_command_pct: 65,
    process_heat_load_w: 145,
    mechanical_load: 0.30
};

flow.set(
    "pendingControl",
    pending
);

return [
    {
        payload:
            pending.control_mode
    },
    {
        payload:
            pending.speed_command_pct
    },
    {
        payload:
            pending.process_heat_load_w
    },
    {
        payload:
            pending.mechanical_load
    },
    {
        payload:
            pending
    }
];

var state = msg.payload || {};

var arrivalText =
    state.interArrivalMs === null
        ? "Initialising"
        : state.interArrivalMs + " ms";

return [
    {
        payload:
            state.assetId
    },
    {
        payload:
            state.modelVersion
    },
    {
        payload:
            state.schemaVersion
    },
    {
        payload:
            state.sequenceId
    },
    {
        payload:
            state.streamStatus +
            " | " +
            arrivalText
    },
    {
        payload:
            state.synchronisationStatus
    },
    {
        payload:
            state.controlMode +
            " | " +
            state.operatingMode
    },
    {
        payload:
            state.healthStatus +
            " | " +
            state.faultCode
    }
];

flow.set(
    "loggingActive",
    false
);

flow.set(
    "experimentPhase",
    "ABORTED"
);

var timers =
    context.get(
        "experimentTimers"
    ) || [];

timers.forEach(
    function(timer) {
        clearTimeout(timer);
    }
);

context.set(
    "experimentTimers",
    []
);

return [
    {
        payload: {
            clear_fault:
                true
        }
    },
    {
        payload:
            "STOPPED — CSV retained; active fault cleared"
    }
];

flow.set("loggingActive", false);
msg.payload = "IDLE — press START NEW 20-MIN RUN";
return msg;

var statusCode =
    Number(msg.statusCode || 200);

if (
    statusCode >= 200 &&
    statusCode < 300
) {
    msg.payload =
        "ONLINE — model inference active";
} else {
    msg.payload =
        "AI service returned HTTP " +
        statusCode;
}

return msg;

var config =
    flow.get(
        "experimentConfig"
    ) || {
        fault_code: "F1",
        fault_severity: 0.6,
        replicate: 1
    };

if (
    msg.topic ===
    "fault_code"
) {
    config.fault_code =
        String(msg.payload);
}

if (
    msg.topic ===
    "fault_severity"
) {
    config.fault_severity =
        Number(msg.payload);
}

if (
    msg.topic ===
    "replicate"
) {
    config.replicate =
        Math.max(
            1,
            Math.floor(
                Number(
                    msg.payload
                ) || 1
            )
        );
}

if (
    config.fault_code ===
    "F0"
) {
    config.fault_severity =
        0;
}

flow.set(
    "experimentConfig",
    config
);

flow.set(
    "selectedFaultCode",
    config.fault_code
);

flow.set(
    "selectedFaultSeverity",
    config.fault_severity
);

flow.set(
    "selectedReplicate",
    config.replicate
);

msg.payload =
    config;

return msg;

var config = {
    fault_code: "F1",
    fault_severity: 0.6,
    replicate: 1
};

flow.set(
    "experimentConfig",
    config
);

flow.set(
    "selectedFaultCode",
    config.fault_code
);

flow.set(
    "selectedFaultSeverity",
    config.fault_severity
);

flow.set(
    "selectedReplicate",
    config.replicate
);

flow.set(
    "loggingActive",
    false
);

flow.set(
    "experimentPhase",
    "IDLE"
);

flow.set(
    "experimentRunId",
    ""
);

return [
    {
        payload:
            config.fault_code
    },
    {
        payload:
            config.fault_severity
    },
    {
        payload:
            config.replicate
    },
    {
        payload:
            config
    },
    {
        payload:
            "IDLE — configure scenario and press START 10-MIN EXPERIMENT"
    }
];

var state =
    msg.payload || {};

return [
    {
        payload:
            state.experimentPhase ||
            "IDLE"
    },
    {
        payload:
            state.faultCode ||
            "F0"
    },
    {
        payload:
            state.faultLabel ||
            "healthy"
    },
    {
        payload:
            Number(
                state.faultSeverity ||
                0
            )
    },
    {
        payload:
            Number(
                state.healthOverall ||
                100
            )
    }
];
